#include <stdint.h>
#include <stddef.h>

// Function under test (from image_parser.c)
extern int parse_image(const uint8_t *buf, size_t len);

int LLVMFuzzerTestOneInput(const uint8_t *data, size_t size) {
    if (size < 8) return 0;        // skip inputs too small for a header
